import{z as l,x as B,o as e,c as d,q as t,j as i,D as E,d as s,s as o,S as r,b as A}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"DNS 缓存投毒","description":"","frontmatter":{"title":"DNS 缓存投毒","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dns-cache-poisoning.md","filePath":"cs/dns-cache-poisoning.md","lastUpdated":1791063341000}'),p={name:"cs/dns-cache-poisoning.md"};function D(C,a,S,c,h,m){const n=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="dns-缓存投毒" tabindex="-1">DNS 缓存投毒 <a class="header-anchor" href="#dns-缓存投毒" aria-label="Permalink to &quot;DNS 缓存投毒&quot;">​</a></h1><div class="epigraph"><p>解析器若把错误的 A 记录缓存起来，随后的 TLS 会连到攻击者的 IP——证书验证仍可能失败，但用户会看到错误页或被诱去关校验。投毒打的是名称到地址的映射，不是 AES。</p><footer>—— 据 Kaminsky 对缓存投毒的公开分析；RFC 5452；RFC 4033 DNSSEC</footer></div><p>上一课<a href="/cs/wpa2-wpa3">WPA</a>保护最后一跳。缺口是<strong>名字</strong>：应用信任主机名，IP 来自 DNS。主干<a href="/cs/dns">DNS</a>已有查询。本课收缓存污染与事务端口/ID 随机化，以及 DNSSEC 的真假。不给投毒操作程序。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>递归解析器接受一条伪造应答并缓存，TTL 期内全网客户被指向错 IP。Kaminsky：扩大碰撞面。防御：源端口随机、DNSSEC 验签、DoT/DoH 对路径保密。缺口是解析信任，不是再讲记录类型。</p><p><span class="marginnote">数字实例：传统应答只有 16 位事务 ID，约 6.5 万种可能；Kaminsky 式攻击用大量查询放大碰撞机会。防御把源端口也随机化（16 位）后，组合涨到约 40 亿种，命中从「试几次」变成「基本试不中」。</span></p><h3 id="tls-仍要验名" tabindex="-1">TLS 仍要验名 <a class="header-anchor" href="#tls-仍要验名" aria-label="Permalink to &quot;TLS 仍要验名&quot;">​</a></h3><p>投毒后证书名不匹配应失败。用户点「继续」才把投毒兑现成保密失败。</p><p><span class="marginnote">RFC 5452 随机化。DNSSEC 验的是区签名链，部署不完整。本课禁止写伪造应答的实验指导。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画查询 ID 与端口的匹配窗口。对照：路径加密（DoH）防窃听与部分篡改，但不自动给端到端区真实性——那是 DNSSEC。应用应钉证书或 DANE（点名即可）。</p><p><span class="marginnote">常见误区：以为上了 DoH/DoT 就万事大吉。它们只是把「你问了什么」装进加密信封，防路上偷看与半路篡改；记录本身是真是假，仍要 DNSSEC 的签名链说话。加密管道里送来的也可能是伪造数据。</span></p>',13)),(e(),i(r,null,{default:E(()=>[o(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20CACHE%5B%22%E9%80%92%E5%BD%92%E7%BC%93%E5%AD%98%22%5D%0A%20%20FAKE%5B%22%E4%BC%AA%E9%80%A0%E5%BA%94%E7%AD%94%22%5D%20--%3E%20CACHE%0A%20%20CACHE%20--%3E%20IP%5B%22%E9%94%99%E8%AF%AF%20IP%22%5D%0A%20%20DNSSEC%5B%22DNSSEC%22%5D%20--%3E%20V%5B%22%E9%AA%8C%E7%AD%BE%E5%88%99%E6%8B%92%E5%81%87%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[s("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"身份链从证书回退到名字，名字回退到解析。下一课 ARP：同一局域网里更短的映射，IP 到 MAC。",-1)),(e(),i(r,null,{default:E(()=>[o(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A7%A3%E6%9E%90%E5%99%A8%E5%8F%91%E5%87%BA%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20RACE%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E4%B8%8E%E7%9C%9F%E6%9D%83%E5%A8%81%E8%B5%9B%E8%B7%91%22%5D%0A%20%20RACE%20--%3E%20GUESS%5B%22%E4%BC%AA%E5%8C%85%E9%A1%BB%E5%90%8C%E6%97%B6%E7%8C%9C%E5%AF%B9%EF%BC%9A%E6%BA%90%E7%AB%AF%E5%8F%A3%20%2B%20%E4%BA%8B%E5%8A%A1%20ID%22%5D%0A%20%20GUESS%20--%3E%20HIT%5B%22%E5%85%A8%E5%AF%B9%EF%BC%9A%E4%BC%AA%E5%BA%94%E7%AD%94%E8%A2%AB%E6%8E%A5%E5%8F%97%E5%B9%B6%E7%BC%93%E5%AD%98%22%5D%0A%20%20GUESS%20--%3E%20MISS%5B%22%E4%BB%BB%E4%B8%80%E4%B8%8D%E5%AF%B9%EF%BC%9A%E5%8C%85%E8%A2%AB%E4%B8%A2%E5%BC%83%22%5D%0A%20%20Q%20--%3E%20REAL%5B%22%E7%9C%9F%E5%BA%94%E7%AD%94%E5%85%88%E5%88%B0%EF%BC%9A%E7%AA%97%E5%8F%A3%E5%85%B3%E9%97%AD%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">为什么重要：TLS 证书校验是投毒得手后的最后一道安全带——名字对不上就断开。可现实中用户见到警告常点「继续访问」，安全带等于自己解开；所以现代浏览器对证书错误默认不给「继续」按钮，正是为这类场景兜底。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部 Kaminsky 变体写成菜谱。ARP 欺骗下一课：二层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无线之后，名字解析是下一跳信任。</li><li>缓存投毒污染 A/AAAA；TLS 名检查是安全带。</li><li>随机化、DNSSEC、加密传输分层补。</li><li>下一课 ARP 欺骗。</li><li>出处：RFC 5452；RFC 4033；Kaminsky（作为历史分析点名）。</li></ul>',5))])}const _=l(p,[["render",D]]);export{T as __pageData,_ as default};
